sys_security_acl.script:
if (gs.getUser().isMemberOf('NowTraining Managers')) {
    var managerID = gs.getUserID();
    var trainingID = current.sys_id();

    var grEnroll = new GlideRecord('x_221517_nowtrai_0_enrollment');
    grEnroll.addQuery('training', trainingID);
    grEnroll.query();

    while (grEnroll.next()) {
        if (grEnroll.student.manager.sys_id == managerID) {
            answer = true;
            break;
        }
    }
} else {
    answer = false;
}
